/**
 * Browsable surface panoramas, one or more per landing site.
 *
 * GENERATED by `tools/moon-textures/moon_panoramas.py` - edit the manifest there, not this
 * file. Each entry carries the geometry the viewer needs: the azimuth the centre of the
 * image faces and the azimuth span it covers, both degrees clockwise from selenographic
 * north, plus the vertical field of view of the frame.
 *
 * `headingDeg` is 0 until the source frames' own headings are recovered from the Apollo
 * Image Atlas. A zero heading means the placement is unverified and the viewer says so
 * rather than implying the panorama is oriented correctly.
 */

export interface MoonPanorama {
  id: string
  siteId: string
  title: string
  caption: string
  /** Path under the public directory. */
  file: string
  width: number
  height: number
  /** Azimuth of the image centre, degrees clockwise from north. 0 = unverified. */
  headingDeg: number
  /** Azimuth span covered by the image, in degrees. 360 means it closes. */
  spanDeg: number
  /** How `spanDeg` is known: 'documented', 'closes', or 'modelled'. */
  spanSource: 'documented' | 'closes' | 'modelled'
  /** Vertical field of view of the frame, in degrees. */
  verticalFovDeg: number
  /** Source frames the stitch was built from. */
  sourceFrames: string
  credit: string
  licence: string
}

