/** Every panorama published for a site, in manifest order. */
export function panoramasForSite(siteId: string): MoonPanorama[] {
  return MOON_PANORAMAS.filter((panorama) => panorama.siteId === siteId)
}

export function findPanorama(id: string): MoonPanorama | null {
  return MOON_PANORAMAS.find((panorama) => panorama.id === id) ?? null
}
